<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { obtenerPlano, type ComponentePlano, type SistemaPlano } from '../services/planos'
const systems=ref<SistemaPlano[]>([]),systemId=ref(''),selectedSystem=ref<SistemaPlano>(),components=ref<ComponentePlano[]>([]),selected=ref<ComponentePlano|null>(null),loading=ref(false),error=ref('')
const allPoints=computed(()=>components.value.flatMap(x=>x.puntos)),bounds=computed(()=>{const p=allPoints.value;if(!p.length)return{minLat:-18,maxLat:0,minLng:-82,maxLng:-68};const lats=p.map(x=>x.latitud),lngs=p.map(x=>x.longitud);let minLat=Math.min(...lats),maxLat=Math.max(...lats),minLng=Math.min(...lngs),maxLng=Math.max(...lngs);const latPad=Math.max((maxLat-minLat)*.12,.002),lngPad=Math.max((maxLng-minLng)*.12,.002);return{minLat:minLat-latPad,maxLat:maxLat+latPad,minLng:minLng-lngPad,maxLng:maxLng+lngPad}})
function x(longitude:number){const b=bounds.value;return((longitude-b.minLng)/(b.maxLng-b.minLng))*1000}function y(latitude:number){const b=bounds.value;return 600-((latitude-b.minLat)/(b.maxLat-b.minLat))*600}function polyline(item:ComponentePlano){return item.puntos.map(p=>`${x(p.longitud)},${y(p.latitud)}`).join(' ')}
async function load(){loading.value=true;error.value='';selected.value=null;try{const r=await obtenerPlano(systemId.value);systems.value=r.sistemas;selectedSystem.value=r.sistema;components.value=r.componentes}catch(e){error.value=e instanceof Error?e.message:'No se pudo cargar el plano.'}finally{loading.value=false}}
const pointCount=computed(()=>components.value.filter(x=>x.puntos.length===1).length),lineCount=computed(()=>components.value.filter(x=>x.puntos.length>1).length)
onMounted(load)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Operaciones / Sistemas y componentes / Planos</nav><header class="hero"><div class="mark">PL</div><div><small>DANA · INFRAESTRUCTURA</small><h1>Plano operacional</h1><p>Visualiza los componentes de agua potable y alcantarillado.</p></div><label>Sistema<select v-model="systemId" @change="load"><option value="">Plano general</option><option v-for="item in systems" :key="item.id" :value="item.id">{{item.distrito}} · {{item.tipo}} · {{item.nombre}}</option></select></label></header><p v-if="error" class="flash">{{error}}</p><section class="summary"><article><small>SISTEMA SELECCIONADO</small><b>{{selectedSystem?.nombre||'Plano general'}}</b><span>{{selectedSystem?.distrito||'Cobertura nacional'}}</span></article><article><small>COMPONENTES</small><b>{{components.length}}</b></article><article><small>INFRAESTRUCTURA PUNTUAL</small><b>{{pointCount}}</b></article><article><small>TRAMOS Y REDES</small><b>{{lineCount}}</b></article></section><section class="layout"><main><header><div><small>VISOR GEOGRÁFICO</small><h2>{{selectedSystem?`${selectedSystem.distrito} · ${selectedSystem.nombre}`:'Plano general de sistemas'}}</h2></div><div class="legend"><span><i class="dot"></i>Punto</span><span><i class="line"></i>Tramo</span></div></header><div v-if="loading" class="empty">Cargando información geográfica…</div><div v-else-if="!components.length" class="empty">Seleccione un sistema con componentes georreferenciados.</div><div v-else class="map"><svg viewBox="0 0 1000 600" preserveAspectRatio="xMidYMid meet"><defs><pattern id="grid" width="50" height="50" patternUnits="userSpaceOnUse"><path d="M 50 0 L 0 0 0 50" fill="none" stroke="#dfe8e9" stroke-width="1"/></pattern></defs><rect width="1000" height="600" fill="#f4f8f7"/><rect width="1000" height="600" fill="url(#grid)"/><g v-for="item in components" :key="item.id" class="feature" @click="selected=item"><polyline v-if="item.puntos.length>1" :points="polyline(item)" fill="none" :stroke="item.color||'#e38b2f'" :stroke-width="Math.max(4,item.grosor||3)" stroke-linecap="round" stroke-linejoin="round"/><g v-else-if="item.puntos[0]" :transform="`translate(${x(item.puntos[0].longitud)} ${y(item.puntos[0].latitud)})`"><circle r="13" :fill="item.color||'#e38b2f'" stroke="#fff" stroke-width="4"/><circle r="4" fill="#fff"/></g></g></svg><div class="map-label">Representación referencial basada en coordenadas registradas</div></div></main><aside><header><small>DETALLE DE INFRAESTRUCTURA</small><h2>{{selected?'Componente seleccionado':'Seleccione un elemento'}}</h2></header><template v-if="selected"><div class="selected-icon" :style="{background:selected.color||'#e38b2f'}">⌖</div><h3>{{selected.nombre}}</h3><span class="type">{{selected.tipo}}</span><p>{{selected.observacion}}</p><dl><div><dt>Condición</dt><dd>{{selected.condicion}}</dd></div><div><dt>Geometría</dt><dd>{{selected.puntos.length>1?'Tramo / red':'Ubicación puntual'}}</dd></div><div><dt>Puntos registrados</dt><dd>{{selected.puntos.length}}</dd></div></dl><h4>Coordenadas</h4><ol><li v-for="(point,index) in selected.puntos" :key="index"><b>P{{index+1}}</b><span>{{point.latitud.toFixed(6)}}, {{point.longitud.toFixed(6)}}</span></li></ol><button>Ver ficha completa →</button></template><div v-else class="aside-empty">Haz clic sobre un punto o tramo del plano para consultar su información.</div></aside></section></div></template>
